# Non-destructive source-authored detail pass: shingles, bark, leaf highlights and flowers.
import random
for name in ['pine','autumn','blossom']:
 path=P/(name+'.svg');s=path.read_text();r=random.Random(name);detail=''
 if name=='pine':
  for top,width in [(55,27),(90,39),(130,49)]:
   for i in range(12):
    x=80+r.uniform(-width,width);y=top+r.uniform(-10,19)
    detail+=f'<path d="M{x:.1f} {y:.1f}l-4 5 7-2" fill="none" stroke="#d6ddad" opacity=".22" stroke-width="1.2"/>'
 else:
  for cy,rx,ry in [(61,30,22),(94,43,26),(134,51,29)]:
   for i in range(25):
    import math
    a=r.random()*math.tau;rr=r.random()**.5;x=80+math.cos(a)*rx*rr;y=cy+math.sin(a)*ry*rr
    color=('#fff0c4' if name=='autumn' else '#fff0e0') if i%3 else ('#b88364' if name=='autumn' else '#c489a5')
    detail+=f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="{2+r.random()*3:.1f}" ry="{1+r.random()*2:.1f}" fill="{color}" opacity=".4" transform="rotate({r.randrange(-60,60)} {x:.1f} {y:.1f})"/>'
 detail+='<path d="M75 159l-2 23m9-27l2 17m-6-13l5-4" fill="none" stroke="#d4a583" opacity=".5" stroke-width="1.5"/>'
 path.write_text(s.replace('</svg>',detail+'</svg>'))
